        .topbar { height: 61px; display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 0 25px; border-bottom: 1px solid var(--line); } .brand { display: flex; align-items: center; gap: 10px; color: var(--muted); font-size: 14px; white-space: nowrap; } .brand img { width: 28px; height: 28px; border-radius: 50%; object-fit: cover; } .brand strong { color: var(--ink); } .top-search, .search { display: flex; align-items: center; gap: 10px; border: 1px solid var(--line); border-radius: 8px; color: #999; background: #fff; } .top-search { width: min(385px, 34vw); padding: 9px 12px; } .top-search input, .search input { width: 100%; border: 0; outline: 0; color: var(--ink); background: transparent; font-size: 13px; } .shortcut { padding: 3px 7px; border: 1px solid var(--line); border-radius: 4px; font-size: 10px; white-space: nowrap; } .top-actions { display: flex; align-items: center; gap: 8px; } .back-dashboard { padding: 9px 13px; border: 1px solid var(--line); border-radius: 8px; color: var(--ink); background: #fff; font-size: 12px; font-weight: 700; } .icon-button { width: 39px; height: 39px; border: 1px solid var(--line); border-radius: 8px; color: var(--muted); background: #fff; }
