        .panel { overflow: hidden; border: 1px solid var(--line); border-radius: 7px; } .panel-top { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 22px; border-bottom: 1px solid #f0f0f0; } .tabs { display: flex; gap: 4px; padding: 4px; border: 1px solid var(--line); border-radius: 7px; } .tab { padding: 9px 15px; border: 0; border-radius: 5px; color: var(--muted); background: transparent; font-size: 12px; cursor: pointer; } .tab.active { color: #fff; background: var(--ink); font-weight: 800; } .panel-actions { display: flex; align-items: center; gap: 8px; } .button { padding: 10px 13px; border: 1px solid var(--line); border-radius: 7px; color: var(--ink); background: #fff; font-size: 12px; font-weight: 800; cursor: pointer; } .button.primary { border-color: var(--ink); color: #fff; background: var(--ink); }
        .count { padding: 0 22px 16px; color: var(--muted); font-size: 12px; text-align: right; } .form-panel { display: none; padding: 20px 22px; border-bottom: 1px solid var(--line); background: var(--soft); } .form-panel.open { display: block; } .form-panel h2 { margin: 0 0 16px; font-size: 17px; } .form-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; } .field { display: grid; gap: 6px; } .field label { font-size: 11px; font-weight: 800; } .field input, .field select, .field textarea { width: 100%; padding: 9px; border: 1px solid #ddd; border-radius: 7px; background: #fff; font-size: 13px; } .field textarea { min-height: 38px; resize: vertical; } .form-footer { display: flex; justify-content: end; gap: 8px; margin-top: 15px; }
        .table-wrap { overflow-x: auto; } table { width: 100%; min-width: 1100px; border-collapse: collapse; } th, td { padding: 14px 23px; border-bottom: 1px solid #eeeeee; text-align: left; vertical-align: middle; } th { color: #626262; background: #fcfcfc; font-size: 10px; letter-spacing: .14em; text-transform: uppercase; white-space: nowrap; } td { color: #555; font-size: 13px; } tbody tr:hover { background: #fffef3; } tbody tr:last-child td { border-bottom: 0; } .number { width: 58px; color: #777; font-size: 12px; } .date { min-width: 110px; color: #777; white-space: nowrap; } .transaction { min-width: 150px; color: var(--ink); font-size: 11px; font-weight: 800; } .resident { min-width: 160px; color: var(--ink); font-weight: 700; } .resident small, .room small { display: block; margin-top: 4px; color: #999; font-size: 11px; font-weight: 400; } .room { min-width: 220px; } .method { display: inline-flex; padding: 5px 10px; border: 1px solid #add4ff; border-radius: 99px; color: var(--blue); background: #f0f7ff; font-size: 10px; font-weight: 800; white-space: nowrap; } .method.manual { border-color: #ddd; color: #666; background: #fafafa; } .description { min-width: 180px; color: #777; } .proof { color: var(--blue); font-size: 11px; font-weight: 800; white-space: nowrap; } .proof { color: var(--blue); font-size: 11px; font-weight: 800; white-space: nowrap; } .total { min-width: 145px; color: var(--ink); font-weight: 800; white-space: nowrap; } .action { padding: 8px 12px; border: 1px solid var(--line); border-radius: 7px; color: #555; background: #fff; font-size: 12px; cursor: pointer; } .delete { border-color: #ffc5c5; color: var(--red); } .locked { color: #999; font-size: 11px; } .empty { padding: 48px; color: var(--muted); text-align: center; } .pagination { padding: 15px 22px; border-top: 1px solid var(--line); }
        .notice, .errors { margin-bottom: 16px; padding: 12px 15px; border-radius: 8px; font-size: 13px; } .notice { color: #166534; background: #ecfdf5; } .errors { color: var(--red); background: #fff1f1; }
        @media (max-width: 900px) { .top-search { display: none; } .page-search { width: 100%; margin: 0 0 20px; } .panel-top { align-items: flex-start; flex-direction: column; } .panel-actions { width: 100%; justify-content: space-between; } .form-grid { grid-template-columns: repeat(2, 1fr); } } @media (max-width: 550px) { .topbar { padding: 0 15px; } main { padding: 25px 14px 45px; } .form-grid { grid-template-columns: 1fr; } .tabs { width: 100%; } .tab { flex: 1; } }
        html[data-theme="dark"] body { color: #f4f4f4; background: #111; } html[data-theme="dark"] .topbar, html[data-theme="dark"] .panel, html[data-theme="dark"] .card, html[data-theme="dark"] .form-panel { background: #191919; border-color: #333; } html[data-theme="dark"] .top-search, html[data-theme="dark"] .search, html[data-theme="dark"] .icon-button, html[data-theme="dark"] .button { color: #eee; background: #191919; border-color: #444; } html[data-theme="dark"] input, html[data-theme="dark"] select, html[data-theme="dark"] textarea { color: #eee; background: #222; border-color: #444; } html[data-theme="dark"] th { background: #202020; } html[data-theme="dark"] td, html[data-theme="dark"] th { border-color: #333; } html[data-theme="dark"] .brand strong, html[data-theme="dark"] h1, html[data-theme="dark"] h2 { color: #fff; }
        :root { --ink: #17201d; --muted: #68736f; --line: #e5e9e6; --soft: #f7f9f6; }
        body { background: radial-gradient(circle at 90% 0, #e9f7c8 0, transparent 28%), #f4f7f3; } .topbar { position: sticky; top: 0; z-index: 4; height: 68px; padding: 0 34px; background: rgba(255,255,255,.9); backdrop-filter: blur(16px); } main { max-width: 1560px; padding: 42px 34px 70px; } .panel { border-radius: 16px; box-shadow: 0 14px 40px rgba(23,32,29,.07); } .button { border-radius: 10px; } th { background: #fbfcfa; color: #68736f; } td { color: #34413c; } tbody tr:hover { background: #f7faed; }
        html[data-theme="dark"] body { color: #f3f7f4; background: #101412; } html[data-theme="dark"] .topbar, html[data-theme="dark"] .panel, html[data-theme="dark"] .form-panel { background: #1a211e; border-color: #35413b; } html[data-theme="dark"] th { color: #dce7e0; background: #26312b; border-color: #405047; } html[data-theme="dark"] td { color: #d7e1da; border-color: #35413b; } html[data-theme="dark"] tbody tr:hover { background: #29362d; } html[data-theme="dark"] h1, html[data-theme="dark"] h2, html[data-theme="dark"] .brand strong { color: #f3f7f4; } html[data-theme="dark"] input, html[data-theme="dark"] select, html[data-theme="dark"] textarea, html[data-theme="dark"] .search, html[data-theme="dark"] .action { color: #f3f7f4; background: #202923; border-color: #4a5a50; }
        .page-head { align-items: end; margin-bottom: 30px; }
        .page-head h1 { font-size: clamp(28px, 3vw, 36px); letter-spacing: -.06em; }
        .page-head .intro { margin-bottom: 0; }
        .page-search { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; width: 100%; margin: 0 0 18px; padding: 14px 16px; border: 1px solid var(--line); border-radius: 16px; background: rgba(255,255,255,.82); box-shadow: 0 14px 40px rgba(23,32,29,.07); }
        .page-search input[name="search"] { flex: 1 1 270px; min-width: 220px; }
        .page-search input[type="date"] { width: 145px; padding: 9px; border: 1px solid var(--line); border-radius: 8px; }
        .page-search .button { white-space: nowrap; }
        .panel { border-radius: 16px; box-shadow: 0 14px 40px rgba(23,32,29,.07); }
