        html[data-theme="dark"] .summary strong + span { border-color: #4a5a50; }
        @media (max-width: 800px) { .summary { align-items: flex-start; flex-wrap: wrap; } .summary strong + span { padding-left: 0; border-left: 0; } .page-search input[type="date"] { flex: 1 1 145px; } }
