<body>
    <header class="topbar"><a class="brand" href="{{ route('admin.dashboard') }}"><img src="{{ asset('images/logo-siap-kukar.png') }}" alt="Logo Asrama Putri Junjung Buyah Kukar YK"><span>Asrama Putri Junjung Buyah Kukar YK</span><span>›</span><strong>Keuangan</strong></a><div class="top-search"><span>⌕</span><input id="global-search" placeholder="Cari kamar, penghuni, pembayaran..."><span class="shortcut">Ctrl K</span></div><div class="top-actions"><a class="back-dashboard" href="{{ route('admin.dashboard') }}">Kembali ke Dashboard</a><button class="icon-button" type="button" aria-label="Notifikasi">♧</button><button class="icon-button" type="button" id="theme-toggle" aria-label="Ganti mode warna">☼</button></div></header>
    <main><h1>Keuangan</h1><p class="intro">Kelola pemasukan dan pengeluaran dalam satu halaman dengan tab terpisah.</p><form class="search page-search" method="GET" action="{{ route('admin.keuangan.index') }}"><span>⌕</span><input name="search" value="{{ $search }}" placeholder="Cari transaksi, penghuni, keterangan..."><input type="hidden" name="jenis" value="{{ $jenis }}"><input type="date" name="mulai" value="{{ $mulai ?? '' }}"><input type="date" name="sampai" value="{{ $sampai ?? '' }}"><button class="button" type="submit">Terapkan</button></form>
        @if (session('success')) <div class="notice">{{ session('success') }}</div> @endif @if ($errors->any()) <div class="errors"><ul>@foreach ($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div> @endif
        <section class="panel"><div class="panel-top"><div class="tabs"><a class="tab {{ $jenis === 'pemasukan' ? 'active' : '' }}" href="{{ route('admin.keuangan.index', ['jenis' => 'pemasukan']) }}">Pemasukan</a><a class="tab {{ $jenis === 'pengeluaran' ? 'active' : '' }}" href="{{ route('admin.keuangan.index', ['jenis' => 'pengeluaran']) }}">Pengeluaran</a></div><div class="panel-actions"><a class="button" href="{{ route('admin.laporan') }}">▣ Laporan & Cetak</a><button class="button primary" id="add-button" type="button">+ {{ $jenis === 'pemasukan' ? 'Pemasukan' : 'Pengeluaran' }} Baru</button></div></div><div class="summary"><span>Total pemasukan</span><strong>Rp {{ number_format($pemasukan, 0, ',', '.') }}</strong><span>Total pengeluaran</span><strong>Rp {{ number_format($pengeluaran, 0, ',', '.') }}</strong><span>Saldo kas</span><strong>Rp {{ number_format($pemasukan - $pengeluaran, 0, ',', '.') }}</strong></div><div class="count">Menampilkan {{ $transaksi->total() }} transaksi {{ $jenis }}.</div>
            <div class="form-panel" id="form-panel"><h2>Tambah {{ ucfirst($jenis) }}</h2><form method="POST" action="{{ route('admin.keuangan.store') }}" enctype="multipart/form-data">@csrf<input type="hidden" name="jenis_transaksi" value="{{ $jenis }}"><div class="form-grid"><div class="field"><label>Tanggal</label><input type="date" name="tanggal" value="{{ date('Y-m-d') }}" required></div><div class="field"><label>Kategori</label><select name="kategori" required>@if($jenis === 'pemasukan')<option value="iuran">Iuran</option><option value="donasi">Donasi</option><option value="lain_lain">Lain-lain</option>@else<option value="listrik">Listrik</option><option value="air">Air</option><option value="perbaikan">Perbaikan</option><option value="kegiatan">Kegiatan</option><option value="lain_lain">Lain-lain</option>@endif</select></div><div class="field"><label>Nominal</label><input type="number" name="nominal" min="0.01" step="0.01" required></div><div class="field"><label>Metode Pembayaran</label><select name="metode_pembayaran" required><option value="cash">Cash</option><option value="transfer">Transfer</option></select></div><div class="field"><label>Bukti Pembelian/Pembayaran</label><input type="file" name="bukti_pembayaran" accept=".pdf,.jpg,.jpeg,.png"><small>Opsional · PDF/JPG/PNG, maksimal 3 MB.</small></div><div class="field"><label>Keterangan</label><textarea name="keterangan" maxlength="255" required></textarea></div></div><div class="form-footer"><button class="button" id="cancel-button" type="button">Batal</button><button class="button primary" type="submit">Simpan {{ ucfirst($jenis) }}</button></div></form></div>
            <div class="table-wrap"><table><thead><tr><th class="number">No</th><th>Tanggal</th><th>No Transaksi</th><th>Kategori</th><th>Penghuni</th><th>Kamar</th><th>Metode</th><th>Bukti</th><th>Keterangan</th><th>Total</th><th>Aksi</th></tr></thead><tbody>@forelse ($transaksi as $index => $item)<tr><td class="number">{{ $transaksi->firstItem() + $index }}</td><td class="date">{{ $item->tanggal?->format('d M Y') }}</td><td class="transaction">{{ $item->pembayaran_id ? 'PAY-'.str_pad($item->pembayaran_id, 5, '0', STR_PAD_LEFT) : 'MAN-'.str_pad($item->id, 5, '0', STR_PAD_LEFT) }}</td><td><span class="method">{{ ucfirst(str_replace('_', ' ', $item->kategori ?? 'lain_lain')) }}</span></td><td class="resident">{{ $item->jenis_transaksi === 'pengeluaran' ? 'Bendahara' : ($item->pembayaran?->user?->name ?? '-') }}@if ($item->pembayaran?->user)<small>{{ $item->pembayaran->user->email }}</small>@endif</td><td class="room">{{ $item->pembayaran?->user?->kamar?->nomor_kamar ? 'Kamar '.$item->pembayaran->user->kamar->nomor_kamar : ($item->pembayaran_id ? 'Belum Dialokasikan' : 'Transaksi Manual') }}</td><td><span class="method {{ $item->pembayaran_id ? '' : 'manual' }}">{{ $item->pembayaran?->metode_pembayaran === 'cash' ? 'CASH' : ($item->pembayaran_id ? 'TRANSFER' : ($item->metode_pembayaran ? strtoupper($item->metode_pembayaran) : 'MANUAL')) }}</span></td><td>@if ($item->bukti_pembayaran)<a class="proof" href="{{ asset('storage/'.$item->bukti_pembayaran) }}" target="_blank" rel="noopener">Lihat Bukti</a>@else - @endif</td><td class="description">{{ $item->keterangan }}</td><td class="total">Rp {{ number_format($item->nominal, 0, ',', '.') }}</td><td>@if ($item->pembayaran_id)<span class="locked">Pembayaran</span>@else<form method="POST" action="{{ route('admin.keuangan.destroy', $item) }}" onsubmit="return confirm('Hapus transaksi ini?')">@csrf @method('DELETE')<button class="action delete" type="submit">Hapus</button></form>@endif</td></tr>@empty<tr><td colspan="11" class="empty">Belum ada transaksi {{ $jenis }}.</td></tr>@endforelse</tbody></table></div>@if ($transaksi->hasPages())<div class="pagination">{{ $transaksi->links() }}</div>@endif
        </section>
    </main>
    <script>const panel = document.querySelector('#form-panel'); document.querySelector('#add-button').addEventListener('click', () => panel.classList.toggle('open')); document.querySelector('#cancel-button').addEventListener('click', () => panel.classList.remove('open')); const globalSearch = document.querySelector('#global-search'); const pageSearch = document.querySelector('.page-search input[name="search"]'); globalSearch.addEventListener('input', () => { pageSearch.value = globalSearch.value; }); document.addEventListener('keydown', (event) => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); globalSearch.focus(); } });</script>
<script>const themeToggle=document.querySelector('#theme-toggle');const setTheme=()=>{const dark=document.documentElement.dataset.theme==='dark';themeToggle.textContent=dark?'☀':'☾';themeToggle.onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('admin-theme',next);themeToggle.textContent=next==='dark'?'☀':'☾';};};setTheme();</script></body>
